<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('teacher');$uid=(int)$_SESSION['user_id'];$q=$conn->prepare('SELECT a.teacher_assignment_id,a.school_year_id,s.section_name,s.grade_level,t.strand_code,sub.subject_code,sub.subject_name,y.school_year_name FROM teacher_assignments a JOIN sections s ON s.section_id=a.section_id JOIN strands t ON t.strand_id=s.strand_id JOIN subjects sub ON sub.subject_id=a.subject_id JOIN school_years y ON y.school_year_id=a.school_year_id WHERE a.teacher_id=? AND a.status="active" ORDER BY y.school_year_id DESC,s.section_name,sub.subject_name');$q->bind_param('i',$uid);$q->execute();$rows=$q->get_result();page_start('My classes');echo '<h1>My classes</h1><div class="tablewrap"><table><tr><th>School year</th><th>Class</th><th>Subject</th><th>Grade entry</th></tr>';while($a=$rows->fetch_assoc())echo '<tr><td>'.e($a['school_year_name']).'</td><td>Grade '.e($a['grade_level']).' · '.e($a['strand_code']).' · '.e($a['section_name']).'</td><td>'.e($a['subject_code'].' — '.$a['subject_name']).'</td><td><a href="/spi/teacher/encode-grades.php?assignment='.(int)$a['teacher_assignment_id'].'">Open gradebook</a></td></tr>';echo '</table></div>';page_end();
